diff --git a/broker/firstboot/start.go b/broker/firstboot/start.go
new file mode 100644
index 000000000..d1813b46f
--- /dev/null
+++ b/broker/firstboot/start.go
@@ -0,0 +1,135 @@
+package firstboot
+
+import (
+	"encoding/json"
+	"errors"
+	"fmt"
+
+	"github.com/ghbmrk/agentos/broker/card"
+	"github.com/ghbmrk/agentos/broker/claim"
+)
+
+// Route is the first-boot path a start takes (HW-10).
+type Route string
+
+const (
+	// RouteDownload is a box flashed from the download: no claim code;
+	// the flasher's QR pairs the phone and the card step starts at once.
+	RouteDownload Route = "download"
+	// RouteClaim is a preloaded box: the claim screen first, the card
+	// step only after the claim.
+	RouteClaim Route = "claim"
+	// RouteReinstall is a box that held a claim code and has lost its
+	// claim state: it says "already claimed, reinstall me" and nothing
+	// else (R4).
+	RouteReinstall Route = "reinstall"
+)
+
+// ErrReinstall is what a box on RouteReinstall answers to every setup
+// step.
+var ErrReinstall = errors.New("firstboot: I am already claimed; reinstall me to set me up again")
+
+// BoxConfig configures Begin. Every field is required but Card's optional
+// ones.
+type BoxConfig struct {
+	// Claim opens the claim state; its Store is the seller flow's.
+	Claim claim.Config
+	// Latch is the card step's latch.
+	Latch Store
+	// Reset removes a vault made from a card nobody confirmed
+	// (ResetUnlatched).
+	Reset func() error
+	// Card is the card step's display config.
+	Card card.DisplayConfig
+}
+
+// ClaimScreen is what the claim screen needs (localui.BoxClaim).
+type ClaimScreen interface {
+	Status() claim.Status
+	Claim(code string) (string, error)
+	Claimant(tok string) bool
+}
+
+// CardHold is the Owner Card step as the page and the finish path see it
+// (localui.OwnerCard).
+type CardHold interface {
+	Display() *card.Display
+	Hold() error
+}
+
+// FirstBoot is one start's first-boot path.
+type FirstBoot struct {
+	Route Route
+	// Claim is the claim screen; nil on RouteDownload.
+	Claim ClaimScreen
+	// Card is the card step.
+	Card CardHold
+}
+
+// Begin picks the start's route and builds its steps. It reads the latch
+// first: a latch it cannot read stops the start and resets nothing. A box
+// whose claim state opens is marked preloaded on the latch before
+// anything else, so losing the claim state later routes to reinstall,
+// never to the download path's pairing (ASSUMPTIONS.md F15). An owned box
+// never reaches Begin (agentosd checks its record first).
+func Begin(cfg BoxConfig) (*FirstBoot, error) {
+	if cfg.Latch == nil || cfg.Reset == nil || cfg.Claim.Store == nil {
+		return nil, errors.New("firstboot: incomplete first-boot config")
+	}
+	b, err := cfg.Latch.Load()
+	if err != nil {
+		return nil, err
+	}
+	var cs cardState
+	if b != nil {
+		if err := json.Unmarshal(b, &cs); err != nil {
+			return nil, fmt.Errorf("firstboot: card state: %w", err)
+		}
+	}
+	cl, err := claim.Open(cfg.Claim)
+	switch {
+	case errors.Is(err, claim.ErrNoCode) && cs.Preloaded:
+		return &FirstBoot{Route: RouteReinstall, Claim: reinstall{}, Card: reinstall{}}, nil
+	case errors.Is(err, claim.ErrNoCode):
+		if err := ResetUnlatched(cfg.Latch, cfg.Reset); err != nil {
+			return nil, err
+		}
+		s, err := NewCardStep(cfg.Latch, cfg.Card)
+		if err != nil {
+			return nil, err
+		}
+		return &FirstBoot{Route: RouteDownload, Card: s}, nil
+	case err != nil:
+		return nil, err
+	}
+	if !cs.Preloaded {
+		cs.Preloaded = true
+		m, err := json.Marshal(cs)
+		if err != nil {
+			return nil, err
+		}
+		if err := cfg.Latch.Save(m); err != nil {
+			return nil, fmt.Errorf("firstboot: marking a preloaded box: %w", err)
+		}
+	}
+	if err := ResetUnlatched(cfg.Latch, cfg.Reset); err != nil {
+		return nil, err
+	}
+	c, err := NewClaimedCard(cl, cfg.Latch, cfg.Card)
+	if err != nil {
+		return nil, err
+	}
+	return &FirstBoot{Route: RouteClaim, Claim: c, Card: c}, nil
+}
+
+// reinstall is RouteReinstall's claim screen and card step: claimed to
+// everyone, a claimant to no one, no card.
+type reinstall struct{}
+
+func (reinstall) Status() claim.Status { return claim.Status{Claimed: true, Reinstall: true} }
+func (reinstall) Claim(string) (string, error) {
+	return "", claim.ErrAlreadyClaimed
+}
+func (reinstall) Claimant(string) bool   { return false }
+func (reinstall) Display() *card.Display { return nil }
+func (reinstall) Hold() error            { return ErrReinstall }
diff --git a/broker/firstboot/start_test.go b/broker/firstboot/start_test.go
new file mode 100644
index 000000000..4bfa8117a
--- /dev/null
+++ b/broker/firstboot/start_test.go
@@ -0,0 +1,207 @@
+package firstboot
+
+// REQ: HW-10, HW-1
+
+import (
+	"errors"
+	"io"
+	"strings"
+	"testing"
+
+	"github.com/ghbmrk/agentos/broker/card"
+	"github.com/ghbmrk/agentos/broker/change"
+	"github.com/ghbmrk/agentos/broker/claim"
+)
+
+// startBox is one box's stores across starts: the claim state the seller
+// flow wrote (empty on a download box), the card latch and a vault that
+// counts its resets.
+type startBox struct {
+	claim, latch change.MemStore
+	vault        bool
+	resets       int
+	shown        card.Card
+}
+
+func (b *startBox) begin(t *testing.T) (*FirstBoot, error) {
+	t.Helper()
+	return Begin(BoxConfig{
+		Claim: claim.Config{Store: &b.claim, BootID: func() (string, error) { return "boot-1", nil }},
+		Latch: &b.latch,
+		Reset: func() error { b.resets++; b.vault = false; return nil },
+		Card: card.DisplayConfig{
+			Generate: func(r io.Reader) (*card.Card, error) {
+				c, err := card.Generate(r)
+				if err == nil {
+					b.shown = *c
+				}
+				return c, err
+			},
+			Provision: func(*card.Card) error { b.vault = true; return nil },
+		},
+	})
+}
+
+func (b *startBox) confirm(t *testing.T, d *card.Display) {
+	t.Helper()
+	if d == nil {
+		t.Fatal("no card shown")
+	}
+	w, g := d.Asks()
+	if err := d.Confirm(strings.Fields(b.shown.VaultPassphrase)[w-1], strings.Split(b.shown.RecoveryKey, "-")[g-1]); err != nil {
+		t.Fatal(err)
+	}
+}
+
+func sealedBox(t *testing.T) (*startBox, string) {
+	t.Helper()
+	b := &startBox{}
+	code, err := claim.NewCode(nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := claim.Seal(&b.claim, code, nil, nil); err != nil {
+		t.Fatal(err)
+	}
+	return b, code
+}
+
+// A sealed box takes the claim route: no card before the claim (Display
+// nil, Hold says it waits to be claimed), the card after it.
+func TestBeginRoutesASealedBoxToTheClaim(t *testing.T) {
+	b, code := sealedBox(t)
+	fb, err := b.begin(t)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if fb.Route != RouteClaim || fb.Claim == nil {
+		t.Fatalf("route %q claim %v", fb.Route, fb.Claim)
+	}
+	if fb.Card.Display() != nil || !errors.Is(fb.Card.Hold(), ErrUnclaimed) {
+		t.Fatal("card step before the claim")
+	}
+	if b.resets != 1 {
+		t.Fatalf("an unlatched start resets the vault first: %d", b.resets)
+	}
+	tok, err := fb.Claim.Claim(code)
+	if err != nil || !fb.Claim.Claimant(tok) {
+		t.Fatalf("claim %v", err)
+	}
+	if !errors.Is(fb.Card.Hold(), ErrCardPending) {
+		t.Fatalf("hold after the claim: %v", fb.Card.Hold())
+	}
+	b.confirm(t, fb.Card.Display())
+	if fb.Card.Hold() != nil || !b.vault {
+		t.Fatal("card not confirmed")
+	}
+}
+
+// A bare install (no claim state) takes the download route: the card at
+// once, no claim screen.
+func TestBeginRoutesABareInstallToTheDownloadPath(t *testing.T) {
+	b := &startBox{}
+	fb, err := b.begin(t)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if fb.Route != RouteDownload || fb.Claim != nil {
+		t.Fatalf("route %q claim %v", fb.Route, fb.Claim)
+	}
+	b.confirm(t, fb.Card.Display())
+	if fb.Card.Hold() != nil {
+		t.Fatal("held after the confirm")
+	}
+	// A restart of a confirmed download box is still the download path.
+	fb, err = b.begin(t)
+	if err != nil || fb.Route != RouteDownload || fb.Card.Hold() != nil {
+		t.Fatalf("restart: %+v %v", fb, err)
+	}
+}
+
+// R4: a box that was ever sealed and lost its claim state routes to
+// "already claimed, reinstall me": no card, no pairing, no claim, and the
+// vault is never reset, whether the loss came before or after the confirm.
+func TestBeginRoutesALostClaimStateToReinstall(t *testing.T) {
+	for name, confirm := range map[string]bool{"after the confirm": true, "before the confirm": false} {
+		b, code := sealedBox(t)
+		fb, err := b.begin(t)
+		if err != nil {
+			t.Fatal(err)
+		}
+		if _, err := fb.Claim.Claim(code); err != nil {
+			t.Fatal(err)
+		}
+		if confirm {
+			b.confirm(t, fb.Card.Display())
+		}
+		resets := b.resets
+		b.claim = change.MemStore{} // claim.json deleted
+		fb, err = b.begin(t)
+		if err != nil {
+			t.Fatalf("%s: %v", name, err)
+		}
+		if fb.Route != RouteReinstall {
+			t.Fatalf("%s: route %q", name, fb.Route)
+		}
+		if b.resets != resets {
+			t.Fatalf("%s: reset the vault", name)
+		}
+		if fb.Card.Display() != nil || fb.Card.Hold() == nil || !strings.Contains(fb.Card.Hold().Error(), "reinstall me") {
+			t.Fatalf("%s: card %v", name, fb.Card.Hold())
+		}
+		if st := fb.Claim.Status(); !st.Claimed {
+			t.Fatalf("%s: status %+v", name, st)
+		}
+		if _, err := fb.Claim.Claim(code); !errors.Is(err, claim.ErrAlreadyClaimed) {
+			t.Fatalf("%s: claim %v", name, err)
+		}
+		if fb.Claim.Claimant(strings.Repeat("a", 64)) {
+			t.Fatalf("%s: a claimant", name)
+		}
+	}
+}
+
+// The confirm keeps the sealed-box marker on the latch, and a latch the
+// marker cannot be saved to stops the start before anything is shown.
+func TestTheSealedMarkerSurvivesTheConfirm(t *testing.T) {
+	b, code := sealedBox(t)
+	fb, _ := b.begin(t)
+	fb.Claim.Claim(code)
+	b.confirm(t, fb.Card.Display())
+	raw, _ := b.latch.Load()
+	if !strings.Contains(string(raw), `"card_confirmed":true`) || !strings.Contains(string(raw), `"preloaded":true`) {
+		t.Fatalf("latch %s", raw)
+	}
+
+	b2, _ := sealedBox(t)
+	b2.latch.Fail = errors.New("disk full")
+	if _, err := b2.begin(t); err == nil {
+		t.Fatal("started without the marker")
+	}
+	// An unreadable latch stops the start on every route.
+	b3 := &startBox{}
+	b3.latch.Save([]byte("{"))
+	if _, err := b3.begin(t); err == nil || b3.resets != 0 {
+		t.Fatalf("corrupt latch: %v resets %d", err, b3.resets)
+	}
+}
+
+// ClaimedCard's Display is its card step's: nil before the claim.
+func TestClaimedCardDisplay(t *testing.T) {
+	b, code := sealedBox(t)
+	cl, err := claim.Open(claim.Config{Store: &b.claim, BootID: func() (string, error) { return "b", nil }})
+	if err != nil {
+		t.Fatal(err)
+	}
+	cc, err := NewClaimedCard(cl, &b.latch, card.DisplayConfig{Provision: func(*card.Card) error { return nil }})
+	if err != nil {
+		t.Fatal(err)
+	}
+	if cc.Display() != nil {
+		t.Fatal("display before the claim")
+	}
+	cc.Claim(code)
